"""Explain lockref decrement, lock handoff and dead markers."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1389': ('함께 쓰는 물건의 사용 약속을 하나 줄이되 마지막 약속 하나는 남겨 봅시다. 마지막 정리는 별도의 담당자가 맡도록 구별하는 방법입니다.', '마지막 참조를 남기는 조건부 감소와 반환값을 이해합니다.', '다른 변경이 없을 때 count 3→2, 2→1, 1→1을 쓰세요. 반환은 차례로 1,1,0입니다. 반환 0은 수가 0이 되었다는 뜻이 아니라고 적으세요.', ['참조 수 count는 객체를 계속 사용하겠다는 약속 수입니다. lockref_put_not_zero는 수를 하나 줄이되 0으로 만드는 마지막 감소는 하지 않습니다. 조건은 감소 전 count가 1보다 큰지입니다.', 'CAS 경로의 new.count--는 우선 지역 복사본의 후보를 계산합니다. 바로 다음 old.count <= 1 검사에 걸리면 0을 반환합니다. 후보를 실제 객체에 저장하지 않았으므로 count가 감소한 것은 아닙니다.', 'count가 1보다 클 때 CAS가 성공하면 실제 수가 하나 줄고 1을 반환합니다. 3에서 2가 되든 2에서 1이 되든 반환값은 1입니다. 새 수 자체가 아니라 감소 성공을 알려 주는 값입니다.', 'CAS로 처리하지 못하면 spinlock을 잡고 현재 count > 1인지 다시 확인합니다. 맞으면 감소하고 성공 표시를 만듭니다. 아니면 그대로 두고 실패 표시 0을 돌려줍니다. 이 일반 경로는 반환 전에 잠금을 풉니다.', 'count=1은 1로 남고, 0이나 음수도 이 호출로 줄어들지 않습니다. 음수는 lockref에서 사용 종료 상태를 나타내는 데 쓰입니다. 실패 0만 보고 count가 꼭 0이라고 단정하면 안 됩니다.', '이 함수는 객체를 실제로 반납하는 free를 호출하지 않습니다. 마지막 참조와 메모리 반납은 상위 코드가 정한 수명 규칙에 따라 별도로 처리합니다. 유효한 객체와 count 범위라는 전제도 지켜야 합니다.'], [('다른 변경이 없을 때 count=1에 put_not_zero를 호출하면 어떻게 될까요?', ['count가 0이 되고 성공 1을 반환해요', 'count는 1로 남고 실패 0을 반환해요'], '감소 전 수가 1 이하이면 실제 변경 전에 돌아갑니다. 마지막 약속 하나를 남기는 함수이므로 반환 0을 감소 후 count로 읽으면 안 됩니다.'), ('이 함수가 객체 메모리 반납까지 실행할까요?', ['아니요. 조건에 맞을 때 수만 줄여요', '네. 언제나 마지막 참조를 없애고 반납해요'], '본문에는 free 호출이 없습니다. 마지막 참조를 0으로 줄이지도 않으므로 마지막 정리는 별도 수명 규칙에 따라야 합니다.')]), 'os1390': ('이번 함수는 “성공했어” 대신 줄인 뒤의 숫자를 알려 줍니다. 하지만 빠른 비교 방식으로 처리하지 못하면 직접 다른 방식으로 줄이지 않고 -1로 알려 줍니다.', '감소 후 숫자 반환과 여러 실패 원인을 구별합니다.', 'CAS 성공을 가정하고 count=3이면 결과 2·반환 2, count=1이면 결과 0·반환 0을 쓰세요. CAS가 없는 구성에서는 변경 없음·반환 -1이라고 따로 적으세요.', ['lockref_put_return은 가능한 경우 참조 수를 하나 줄이고 그 직후의 새 count를 돌려줍니다. 앞 수업의 성공 표시 1과 다릅니다. 양수 3을 줄이는 데 성공하면 2를 반환합니다.', 'CAS는 읽은 상태와 현재 상태가 같을 때만 새 값을 쓰는 비교·교환입니다. 이 함수는 후보 new.count를 하나 낮추지만 old.count <= 0이면 -1로 끝내므로 후보가 실제 객체에 저장되지 않습니다.', '양수에서 CAS에 성공하면 new.count를 반환합니다. count=1도 0으로 내려갈 수 있습니다. 반환 0은 여기서는 감소 성공의 새 값입니다. 실패를 0으로 알리는 다른 함수와 섞어 읽지 마세요.', 'CAS 매크로 뒤에는 return -1만 있습니다. spin_lock으로 다시 감소하는 대체 경로가 없습니다. 따라서 CAS를 쓰지 않는 빌드 구성에서는 이 호출이 count를 바꾸지 않고 -1을 반환합니다.', '처음 본 잠금이 잡혀 있거나, 경쟁으로 재시도 한도에 도달해도 -1이 나올 수 있습니다. count가 0 이하일 때도 -1입니다. 그래서 -1만 보고 객체가 반드시 dead라고 판단할 수 없습니다.', '0 이상의 반환에서 이 호출이 감소한 결과를 확인하고, -1이면 감소했다고 가정하지 말고 호출자에게 정해진 다음 처리로 이어가야 합니다. 다른 CPU가 뒤에 수를 바꿀 수 있으므로 반환은 영원히 고정된 현재 수가 아닙니다. 0 반환도 자동 메모리 반납을 뜻하지 않습니다.'], [('CAS를 쓰지 않는 구성에서 put_return은 무엇을 할까요?', ['spinlock을 잡아 반드시 감소해요', '이 호출은 count를 바꾸지 않고 -1을 반환해요'], '매크로 뒤에는 바로 -1 반환만 있고 잠금 대체 경로가 없습니다. 이름이 비슷한 다른 lockref 함수와 본체를 구별해야 합니다.'), ('-1을 받으면 count가 반드시 음수인 dead 상태일까요?', ['아니요. 잠금 보유나 재시도 한도도 원인이에요', '네. 음수 count에서만 -1이 나와요'], 'CAS 경로를 쓸 수 없거나 잠금이 잡힌 상태를 보아도 -1입니다. 하나의 실패 표시를 한 가지 원인만의 증거로 해석하면 안 됩니다.')]), 'os1391': ('사용자가 여럿이면 약속 하나를 줄이고 끝냅니다. 마지막 처리 차례라면 장부의 잠금을 쥔 채 다음 담당자에게 일을 넘깁니다.', '반환값에 따라 달라지는 count와 잠금 보유 상태를 이해합니다.', '경쟁이 없을 때 count=3이면 count=2·반환 1·잠금 미보유, count=1이면 count=1·반환 0·잠금 보유로 표를 만드세요.', ['lockref_put_or_lock은 수를 줄이거나 잠금을 얻어 넘겨주는 두 역할을 합니다. count가 1보다 크면 하나 줄이고 1을 반환합니다. 이 반환은 감소 성공 표시이며 잠금을 보유한 채로 넘기지 않습니다.', 'CAS 경로에서 count <= 1을 보면 반복을 빠져나옵니다. 이때 후보 복사본을 줄였어도 실제 객체에는 쓰지 않습니다. 이어서 spin_lock으로 실제 잠금을 얻습니다.', '잠금을 얻은 뒤 count <= 1인지 다시 확인합니다. 다른 CPU가 그 사이 참조를 늘렸을 수 있어서 재확인이 필요합니다. 여전히 1 이하면 감소하지 않고 0을 반환합니다. 이 경로에는 spin_unlock이 없으므로 호출자가 잠금을 보유합니다.', 'count=1이고 다른 변경이 없다면 반환 0 뒤에도 count는 1입니다. 1을 0으로 만든 뒤 알리는 함수가 아닙니다. 호출자는 잠금 아래서 실제 상태를 확인하고 마지막 처리 규칙을 이어갈 수 있습니다.', '처음 1을 보았어도 잠금을 얻을 때 2가 되어 있다면 일반 경로에서 2를 1로 줄이고 잠금을 푼 뒤 1을 반환합니다. 따라서 처음 읽은 값만으로 마지막 반환 경로를 결정할 수 없습니다.', '반환 0이면 이어받은 잠금을 상위 규칙에 맞게 처리하고 결국 대응하는 해제를 책임져야 합니다. 반환 1이면 이 호출로 잠금을 이어받지 않았으므로 무조건 unlock을 덧붙이면 안 됩니다. 반환, count 변경, 잠금 상태 세 가지를 함께 보세요.'], [('count=1이 유지된 채 반환 0을 받으면 잠금은 어떤 상태일까요?', ['언제나 이미 풀려 있어요', '호출자가 이어서 사용하도록 잡혀 있어요'], '잠금 아래 count <= 1 분기는 unlock 없이 반환합니다. 다음 처리를 잠금으로 보호한 채 이어가도록 맡기는 경로입니다.'), ('반환 0이면 count가 반드시 1에서 0으로 줄었을까요?', ['아니요. 그 분기는 count를 줄이지 않아요', '네. 반드시 0으로 만든 뒤 반환해요'], '0은 잠금을 얻어 넘겨줬다는 경로의 표시입니다. 실제 수를 감소시키는 줄보다 먼저 반환하므로 마지막 상태 처리는 호출자가 이어 가야 합니다.')]), 'os1392': ('물건에 사용 종료 표지를 붙이는 일과 물건을 창고에 반납하는 일은 다릅니다. 종료 표지를 특별한 숫자로 기록해 보겠습니다.', 'dead 표시, 신뢰할 수 있는 조회 조건, 실제 메모리 반납을 구별합니다.', 'count=0과 count=-128을 나란히 쓰세요. count<0 검사의 결과는 각각 거짓·참입니다. -128을 쓰는 동작 옆에 메모리 반납은 별도라고 적으세요.', ['lockref_mark_dead는 count에 -128을 저장합니다. 여기서 음수는 실제로 마이너스 명이 사용한다는 뜻이 아닙니다. 정상 참조 수와 구별하려고 약속한 특별한 상태 표시입니다. 이런 특별한 값을 sentinel이라고 부릅니다.', '먼저 assert_spin_locked(&lockref->lock)가 나옵니다. 호출자가 잠금을 보유해야 한다는 전제를 확인하는 표시입니다. 이 줄이 대신 잠금을 얻어 주는 것은 아닙니다. 진단의 세부 동작은 빌드 설정에 영향을 받을 수 있습니다.', '잠금을 잡고 종료 상태를 기록해야 동시에 수를 바꾸는 다른 코드와 충돌하지 않습니다. 언제 종료 표시를 해도 되는지는 상위 객체의 수명 규칙에 달려 있습니다. 함수 이름만 보고 살아 있는 객체에 임의로 표시하면 안 됩니다.', '헤더의 __lockref_is_dead는 count < 0인지 확인합니다. -128만 같은지 비교하는 것이 아닙니다. 0은 음수가 아니므로 이 검사에서는 dead가 아닙니다. 참조 수 0과 종료 표시를 같은 값으로 취급하지 마세요.', '헤더는 신뢰할 결과를 얻으려면 spinlock 아래에서 이 조회를 하라고 설명합니다. 잠금 없는 숫자 읽기만으로 이후 객체 사용까지 안전하다고 증명할 수는 없습니다. 객체 메모리가 유효하다는 전제도 별도로 필요합니다.', 'mark_dead 본체는 잠금 전제 확인과 count 대입뿐이며 free를 호출하지 않습니다. 종료 표시 이후 참조 획득을 거절하는 함수들과 연결해 사용하고 실제 반납은 별도 단계에서 처리합니다. count를 바꾸는 모든 함수의 조건이 같지는 않으므로 해당 API의 규칙을 확인하세요.'], [('mark_dead가 count에 저장하는 특별한 값은 무엇일까요?', ['0이에요', '-128이에요'], '본문은 count = -128입니다. 정상 수와 구별되는 음수 표시이며, 0과 같다고 외우면 is_dead의 count < 0 검사를 잘못 이해하게 됩니다.'), ('dead 표시를 하면 객체 메모리도 즉시 반납될까요?', ['아니요. 이 함수는 count에 표시만 해요', '네. 항상 allocator에 즉시 반납해요'], '본문에 free 호출은 없습니다. 사용 종료 상태를 기록하는 일과 실제 저장 공간을 반납하는 일은 별도 단계입니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_343.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
